statement:
\begin{lemma}[The boundary laws]
\label{ch:laws}
For each installed body, its initial boundary represents, up to overall
conjugation, a word $L$ in the four based tips satisfying
\begin{equation}
\label{ch:law-properties}
 L\big|_{X_\alpha=1}=1\quad(1\leq\alpha\leq4),
 \qquad
 L\equiv [[X_1,X_2],[X_3,X_4]]
       \pmod{\Gamma_5 F(X_1,X_2,X_3,X_4)}.
\end{equation}
Here $\Gamma_r$ is the lower central series, and orientations are
chosen for the displayed sign.
\end{lemma}

\begin{lemma}[The marked exterior model]
\label{ch:exterior-model}
There is a homotopy-pushout model
\begin{equation}
\label{ch:exterior-pushout}
 E\simeq X\cup_{\coprod_jF_j}\coprod_j(F_j\times S^1),
\end{equation}
where $F_j$ maps to $F_j\times S^1$ by its inward section.  Under
this model the displayed maps from $F_j\times S^1$ are the actual
tube-side maps, and $S^1$ is the normal circle.
\end{lemma}

\begin{proposition}[The chamber homotopy type]
\label{ch:homotopy-type}
With the markings induced by the preceding construction,
\begin{equation}
\label{ch:group-and-spheres}
 H:=\pi_1D=\pi_1X*F(z_1,\ldots,z_k),\qquad
 D\simeq BH\vee\bigvee^{2k}S^2,
\end{equation}
where $BH$ is a finite graph and $z_j$ is the normal-circle generator
of the $j$th replacement.  On the common surgery-link exterior in
the boundary, killing the $z_j$ recovers the original marking into
$\pi_1X$.
\end{proposition}

\begin{lemma}[Algebraic duals]
\label{ch:exterior-duals}
There are proper framed immersed disks $f_j$ in $E$, bounded by
the truncated $a_j$-branch curves, and framed spheres $g_j$ in $E$
such that
\begin{equation}
\label{ch:dual-pairings}
 \lambda(f_i,g_j)=\delta_{ij},\qquad
 \lambda(g_i,g_j)=0
 \quad\text{over }\mathbb Z[\pi_1E].
\end{equation}
Each $g_j$ is embedded with trivial normal bundle.  If all terminal
caps selected for the branch compressions are mutually disjoint,
these representatives have exactly one geometric intersection
between $f_j$ and $g_j$ and no other intersections.
\end{lemma}

\begin{corollary}[Connected lifted boundary]
\label{ch:boundary-surjectivity}
The boundary marking $\pi_1S\to H$ is surjective.
\end{corollary}

\begin{lemma}[Persistence of the chamber data]
\label{ch:cover-data}
For every $d$, the data $(D_d,P_d,S_d,H_d)$ satisfy
Propositions~\ref{ch:homotopy-type} and~\ref{ch:poincare-chamber}
with all the bodies and basis spheres lifted.  In particular,
$S_d$ is connected, $H_d$ is free, $P_d\simeq BH_d$, and
$(P_d,S_d)$ is the oriented Poincar\'e pair obtained by
attaching three-cells to a specified framed immersed
hyperbolic basis of $D_d$.
\end{lemma}

\begin{lemma}\label{ext:lifted-nerve}
The complex $\widehat{\mathcal L}$ is a connected, locally finite,
flag-no-square PL triangulation of the three-manifold $\widehat S$.
The deck action of $H$ is free on its vertices, and its quotient is
$\mathcal L$.  In particular, each vertex link is a PL two-sphere.
\end{lemma}

\begin{proposition}\label{ext:development}
The space $\widetilde Q$ is contractible.  If $\overline x$ and
$x_2$ are the images of $x$ in $P$ and $P_2$, respectively, the
maps
\[
 \begin{aligned}
 [c,x]&\longmapsto[\chi_0(c),\overline x]\in Q^0,\\
 [c,x]&\longmapsto[\chi(c),\overline x]\in Q,\\
 [c,x]&\longmapsto[\chi(c),x_2]\in Q_2
 \end{aligned}
\]
are universal coverings.  With the chosen deck-group convention,
\begin{equation}\label{ext:groups}
 \pi_1(Q^0)=\ker\chi_0,\qquad
 G:=\pi_1(Q)=\ker\chi,\qquad
 \Pi:=\pi_1(Q_2)=\ker\eta .
\end{equation}
The homomorphism $w\colon G\to\mathbb Z$ induced by the folding map
is $w$ composed with the projection $\mathcal E\to H$.
\end{proposition}

\begin{proposition}\label{ext:delta}
With the marking $\pi_1(M)\cong\Pi$, no homeomorphism of $M$
induces the outer automorphism $\delta$.
\end{proposition}

\begin{proposition}\label{ext:nonconjugate}
The subgroups $\mathsf A$ and $\mathsf B_\ell$ of $\Out(\Pi)$
are not conjugate.
\end{proposition}

\begin{proposition}[Odd covers do not fill]
\label{for:odd-nonfilling}
For every odd integer $d\geq3$, the marked boundary $S_d$ admits no
marked filling.
\end{proposition}

\begin{lemma}[Marked cuts]
\label{for:cuts}
A marked filling of $S_d$ gives a compact connected topological
four-manifold $W$ with boundary identified with $\partial X_d$ and
with the marked graph homotopy type of $X_d$.  It admits a decomposition
over $\Gamma_d$ with connected vertex pieces $V_v$ and connected
three-dimensional cuts $Y_e$ such that:
\begin{enumerate}
\item the outside boundary face of $V_v$ is the prescribed $K_v$,
and $\partial Y_e$ is precisely the prescribed join torus;
\item every marked four-slot law at $v$ bounds a disk in $V_v$;
\item the cuts are compact smooth three-manifolds, and the filled
vertex pieces are smooth away from finitely many interior points.
\end{enumerate}
The identifications retain the based port meridians, their longitudes,
and the named extra loops.
\end{lemma}

\begin{proposition}[Formal data from the cuts]
\label{for:formal-data}
For the cut pieces of Lemma~\ref{for:cuts}, there are a
characteristic-zero field $K$, coordinate blocks
$h_e=(h_{e,1},\ldots,h_{e,N_e})$, and algebraic power-series germs
$F_e(h_e),b_e(h_e)$ over $K$, with $F_e(0)=b_e(0)=0$, as follows.
For each vertex set
\begin{equation}
\label{for:vertex-potentials}
 \begin{split}
 T_v&=K[t_e:e\in E_+(v)]/(t_e^2:e\in E_+(v)),\\
 \mathcal S_v&=\sum_{e\in E_+(v)}(F_e+t_eb_e)
                  -\sum_{e\in E_-(v)}F_e.
 \end{split}
\end{equation}
There are smooth formal graph parametrizations $M_v(y_v,t)$ in the
incident $h_e$ blocks over $T_v$, centered modulo $(t)$, such that:
\begin{enumerate}
\item their central tangent maps are injective, and the difference map
from the sum of the vertex tangent spaces to the sum of the edge blocks
is an isomorphism;
\item $\mathcal S_v(M_v)=0$;
\item for $L\in\mathcal L_v$, with $I=L\cap E_+(v)$ and
$J=L\cap E_-(v)$,
\begin{equation}
\label{for:mixed-membership}
 \left(\prod_{i\in I}t_i\right)
 \left(\prod_{j\in J}b_j\right)(M_v)
 \in\bigl((\partial_h\mathcal S_v)(M_v)\bigr)
       \subset T_v[[y_v]].
\end{equation}
\end{enumerate}
Empty products equal one.  In every parameter ring, only the individual
squares $t_e^2$ vanish; mixed products are retained.  One can take
$K=\mathbb C((\sigma))$.
\end{proposition}

\begin{lemma}[Vertex identities with both endpoint signs]
\label{for:vertex-identities}
The flat edge restrictions lift to a formal parametrization
$M_v^{\mathrm{form}}$ over $R_v$ satisfying
\begin{equation}
\label{for:square-gradient}
 \mathcal S_v^{\mathrm{form}}(M_v^{\mathrm{form}})\in\mathcal I_v^2,
 \qquad
 (\partial_h\mathcal S_v^{\mathrm{form}})(M_v^{\mathrm{form}})
                         =L_vr_v,
\end{equation}
where $L_v$ has a full-column minor that is a unit at the joint origin.
With $\sigma$ and the $t_e$ fixed, the tangent maps at the joint origin
are the restriction maps in \eqref{for:tangent-isomorphism}.
\end{lemma}

\begin{lemma}
\label{hyp:bounded-grids}
Every isometric embedding of a square grid of side length \(n\) into
\(X^{(1)}\) satisfies
\[
n\leq 16b_T-1.
\]
\end{lemma}

\begin{lemma}
\label{hyp:grids-to-triangles}
Let \(Y\) be a CAT(0) cube complex.  Suppose every isometrically
embedded square grid in its edge graph has side length at most
\(K\), where \(K\) is a nonnegative integer.  Then any two vertices
of \(I(x,y)\) at the same distance from \(x\) are at distance at most
\(2K\), uniformly in \(x,y\).  Every geodesic triangle with vertex
corners in the edge graph is \(4K\)-thin at its vertices.
\end{lemma}

\begin{proposition}
\label{hyp:word-hyperbolic}
The groups \(\mathcal E\) and \(\Pi\) are word-hyperbolic.
\end{proposition}

\begin{lemma}
\label{hyp:no-vc-splitting}
The group \(\Pi\) admits no nontrivial splitting over a virtually
cyclic subgroup.  It has one end.
\end{lemma}

\begin{proposition}
\label{hyp:finite-out}
The outer automorphism group \(\Out(\Pi)\) is finite.
\end{proposition}

\begin{theorem}\label{thm:pair}
There exist closed connected aspherical topological four-manifolds
$M$ and $N$ that are homotopy equivalent but not homeomorphic.
Their common fundamental group is word-hyperbolic.
\end{theorem}

\begin{theorem}\label{thm:self-map}
There exist a closed connected aspherical topological four-manifold
$M$ and a homotopy equivalence $f\colon M\to M$ such that no
homeomorphism $M\to M$ is homotopic to $f$.
\end{theorem}

\begin{lemma}\label{mod:quotient-cover}
The map \(q\) is a regular finite covering with deck group
\(\mathsf C\).  The space \(Q\) is a connected finite aspherical CW
complex.  The folding map
\begin{equation}\label{mod:folding}
 r:Q\longrightarrow P,\qquad r([b,x])=x,
\end{equation}
is split by the inclusion of any chamber.
\end{lemma}

\begin{proposition}\label{mod:odd-models}
For every odd integer \(d\geq3\), the space \(Q_d\) has no closed
topological four-manifold model.
\end{proposition}

\begin{lemma}\label{nor:conjugating}
Let $X$ be $\widehat{\mathcal L}$ or the link in
$\widehat{\mathcal L}$ of a simplex of dimension $0$, $1$, or
$2$.  If an automorphism $\varphi$ of $W(X)$ sends each vertex
generator to a conjugate of itself, then $\varphi$ is inner.
\end{lemma}

\begin{proposition}\label{nor:rigidity}
Every automorphism of $W$ is a composite of an inner
automorphism and an automorphism induced by a simplicial
automorphism of $\widehat{\mathcal L}$.
\end{proposition}

\begin{proposition}\label{nor:normalizer}
Inside $\Out(\Pi)$,
\begin{equation}\label{nor:normalizer-equality}
 N_{\Out(\Pi)}(\mathsf A)
   =\mathsf A\times\langle\delta\rangle.
\end{equation}
\end{proposition}

\begin{proposition}\label{refl:odd-models}
For every odd integer $d\geq3$, the space $Q^0_d$ has no closed
topological four-manifold model.
\end{proposition}

\begin{lemma}[Graph forms]\label{ten:graph-forms}
Let \(c_1,\ldots,c_r\) be graph equations for a smooth formal graph over
one of the square-free parameter rings, centered modulo its parameter
ideal.  In the truncated differential forms of its ambient space, set
\begin{equation}\label{ten:graph-form}
 U_c=\bigwedge_{s=1}^r c_s^{q-1}\mathrm dc_s.
\end{equation}
Then \(\mathrm dU_c=0\); the graph ideal annihilates \(U_c\); and every
internal one-form restricting to zero on the graph wedges to zero with
\(U_c\).
\end{lemma}

\begin{lemma}[Transverse contraction]\label{ten:nonzero}
The total contraction of \((\omega_v)_{v\in V}\) is nonzero.
\end{lemma}

\begin{lemma}[Lifting a kernel cycle]\label{ten:lift}
Let \(x\in\mathcal K_e\cap\ker\delta_e\) be homogeneous and let \(a\)
be a homogeneous \(D_e\)-cycle representing \(x\).  There is a form
\(a'\) of the same exterior degree such that
\begin{equation}\label{ten:lift-equation}
 (D_e+t\,\mathrm db_e\wedge(-))(a+ta')=0
                       \quad\text{in }\Omega_e[t]/(t^2).
\end{equation}
\end{lemma}

\begin{lemma}[Restriction maps and coordinate slopes]
\label{lem:geometric-edge-cohomology}
The cohomology and slope conclusions of
Proposition~\ref{prop:geometric-reduction} hold.
For each edge piece one also has
\begin{equation}
\label{eq:edge-relative-cohomology}
 H^1(Y_i,\partial Y_i;k)
  \cong\ker\bigl(H^1(Y_i;k)\longrightarrow H^1(\partial Y_i;k)\bigr),
 \qquad b_2(Y_i)=b_1(Y_i)-1.
\end{equation}
\end{lemma}

\begin{lemma}\label{lem:tensor-reduction}
If the data in Theorem~\ref{thm:tensor-obstruction} existed, data satisfying
the same conditions would exist over a field of positive characteristic
\(p\), for arbitrarily large \(p\).  The edge functions would still be
separated in their original blocks.
\end{lemma}

\begin{lemma}\label{lem:tensor-frobenius}
Every formal change of internal coordinates over \(T_p\) that is centered
modulo \((t)\) preserves the ideal
\((z_1^p,\ldots,z_N^p)\).  Hence it induces an automorphism of the truncated
algebra and of its relative differential forms.
\end{lemma}

\begin{lemma}\label{lem:tensor-graph-form}
The form \(U_c\) is \(\dd\)-closed and is annihilated by the graph ideal.
Every internal one-form whose restriction to the graph is zero wedges
to zero with \(U_c\).
For two central graphs with complementary tangents and graph forms
\(U_0,V\),
\begin{equation}\label{eq:tensor-nonzero-pairing}
                     \int U_0\wedge V\ne0 .
\end{equation}
\end{lemma}

\begin{lemma}\label{lem:tensor-membership-boundary}
For every three distinct active indices \(i,j,k\), there are actual forms
\(B_{ijk}\) and \(C_{ijk}\) with
\begin{equation}\label{eq:tensor-actual-boundaries}
 t_i t_j t_k U_t=D_t B_{ijk},\qquad
 b_i b_j b_k V=D C_{ijk}.
\end{equation}
The first equality is over the full parameter algebra \(T_p\).
\end{lemma}

\begin{lemma}[Kernel support]\label{lem:tensor-kernel-support}
Let \(v\in\bigotimes_{i=1}^nH_i\) be killed by
\(B_iB_jB_k\) for every three distinct active indices.
Then \(v\) belongs to the sum of tensor subspaces having all but at most
two active factors in the corresponding \(K_i\).
\end{lemma}

\begin{lemma}
\label{lem:edge-central-ideal}
The curvature ideal of $s(h)$ is the Jacobian ideal
\[
 J=\Jac(f)=\left(\frac{\partial f}{\partial h_1},\ldots,
                 \frac{\partial f}{\partial h_N}\right).
\]
Moreover $f\in\m^3$.
\end{lemma}

\begin{lemma}
\label{lem:edge-affine-ideal}
The function
\begin{equation}
\label{eq:edge-adjusted-potential}
 f_\tau(h)=\mathcal C(s(h,\tau))
                   +\tfrac{\epsilon}{2}\tr(u v(h,\tau))
\end{equation}
has internal Jacobian ideal equal to the full curvature ideal of the
affine slice.  Here the internal derivatives are only the derivatives
with respect to the $h_j$.
\end{lemma}

\begin{lemma}
\label{lem:edge-based-slice}
The central slice identifies its curvature-zero scheme with the formal
scheme of based representations of $\pi_1Y$ satisfying $G_\alpha=1$.
Over the dual numbers, the affine slice identifies its curvature-zero
scheme with the based representations satisfying
$G_\alpha=\exp(-\tau T_0)$.  These statements hold on all local
Artinian coefficient algebras, not only on reduced points.
\end{lemma}

\begin{lemma}
\label{lem:vertex-linear}
After fixing the evaluations on the extra letters and on all plus
meridians, the direct sum of the two vertex degree-one spaces maps
isomorphically, by difference of restrictions, to $\mathcal H$.
Moreover,
\begin{equation}
\label{eq:vertex-h2-isomorphism}
 H^2(A;\mathbb C)\oplus H^2(B;\mathbb C)
       \longrightarrow\bigoplus_i H^2(Y_i;\mathbb C)
\end{equation}
is an isomorphism.  In particular each vertex summand maps injectively.
\end{lemma}

\begin{lemma}
\label{lem:vertex-offshell-identities}
At the joint origin the tangent images of $H_A$ and $H_B$, with the
external parameters fixed, are complementary.  For each vertex,
\begin{equation}
\label{eq:vertex-square-and-gradient}
 S_P(H_P)\in I_P^2,
 \qquad (\partial_h S_P)(H_P)=M_P r_P,
\end{equation}
where $M_P$ is an actual coefficient matrix whose reduction at the
joint origin has full column rank $q_P$.  Consequently the restricted
gradient ideal equals $I_P$.
\end{lemma}

\begin{lemma}
\label{lem:vertex-adjoint-span}
The nine matrices $\Ad(g_{ab}(\sigma))$ span $\End_K(\g\otimes K)$.
\end{lemma}

\begin{lemma}
\label{lem:vertex-triple-ideals}
For any three distinct active edges, the product of their three source
parameters belongs to $I_A$.  At $B$, every product of one matrix entry
from each of their three logarithmic $\beta$ holonomies belongs to
$I_B$.  The same conclusion holds with entries of $G_i-1$ in place of
the logarithmic holonomies.
\end{lemma}

\begin{corollary}
\label{cor:vertex-tensor-interface}
The cut data of Proposition~\ref{prop:geometric-reduction}, with
$m\geq5$ and the indicated finite law list, supply all the hypotheses
of Theorem~\ref{thm:tensor-obstruction}.
\end{corollary}

\begin{corollary}
\label{ch:boundary-homology}
The map $\pi_1S\to H$ is onto.  If $r=\operatorname{rank}H$, then
$H_1(S;\Z)\to H_1(P;\Z)$ is an isomorphism and
$H_2(S;\Z)\cong\Z^r$.
\end{corollary}

\begin{proposition}[Removal of the remaining planes]\label{ct:removal}
The compact manifold $Z$ admits interior surgeries producing a
compact oriented topological four-manifold $V$ with boundary $S$,
fundamental group $H$, and contractible universal cover.  The
boundary map to $BH$ is the original central marking.
\end{proposition}

\begin{proposition}[The reflected pair]
\label{rf:development}
The space $Q$ is a finite oriented Poincar\'e complex of dimension four.
The natural map $f:N\to Q$ has degree one and induces an isomorphism
on fundamental groups, identifying both with the group $G$ in
\eqref{rf:group}.  If $b$ is the total number of chamber hyperbolic
planes in $N$, then
\[
 \pi_2(N)\cong(\Z G)^{2b}
\]
has the specified orthogonal hyperbolic basis, and
$\widetilde H_i(\widetilde N;\Z)=0$ for $i\ne2$.
The group $G$ is finitely presented, is torsion-free, and satisfies
\begin{equation}
 \label{rf:pd}
 H^i(G;\Z G)=0\quad(i\ne4),\qquad
 H^4(G;\Z G)\cong\Z
\end{equation}
with trivial right $G$-action.
\end{proposition}

\begin{lemma}
\label{rf:cat0}
The group $\widehat C\rtimes H$, and hence its finite-index subgroup
$G$, acts properly and cocompactly by isometries on a proper CAT(0)
cube complex of dimension at most five.
\end{lemma}

\begin{lemma}\label{st:quadratic-detection}
With the identifications above,
\begin{equation}\label{st:fundamental-equality}
 (u_N)_*[N]=(u_L)_*[L]\quad\text{in }H_4(B;\Z).
\end{equation}
\end{lemma}

\begin{lemma}\label{st:marked-bordism}
There is an $s$-cobordism $(W;N,L)$ whose two end inclusions identify
$\pi_1$ and $\pi_2$ by the marking of
Proposition~\ref{st:marked-equivalence}.
\end{lemma}

\begin{lemma}[Algebraic replacement of a formal primitive]
\label{alg:replacement}
Let $A$ be the local ring at a complex point of an \'etale
neighborhood of affine $n$-space, with coordinates $v$ centered at that
point, and let $B=\widehat A=\mathbb C[[v]]$. Let $K$ be any ideal of
$A$. Suppose $P\in B$ satisfies
\begin{equation}
 \partial_{v_j}P\in KB,\qquad
 \partial_{v_j}P\in A+K^bB
 \quad\text{for every $j$ and every $b\geq1$}.
 \label{alg:replacement-hyp}
\end{equation}
For every $m\geq1$ there is $P_m\in A$ such that
$P-P_m\in K^mB$. No reducedness, primaryness, or equidimensionality
condition is imposed on $K$.
\end{lemma}

\begin{lemma}[Remainders without numerical denominators]
\label{alg:remainder}
Let $R$ be a commutative ring and
$\Phi(a,C)\in(a,C)^3R[[a,C]]$, where $C$ has $N$ entries. There is an
$N$-by-$N$ matrix $H(a,C,\delta)$ over $R[[a,C,\delta]]$, with every
entry in $(a,C,\delta)$, such that
\begin{equation}
 \Phi(a,C+\delta)
 =\Phi(a,C)+(\partial_C\Phi)(a,C)^{\mathsf T}\delta
        +\delta^{\mathsf T}H(a,C,\delta)\delta.
 \label{alg:remainder-formula}
\end{equation}
There is also a matrix $G(a,C,\delta)$ with positive-order entries
satisfying
\begin{equation}
 (\partial_C\Phi)(a,C+\delta)-(\partial_C\Phi)(a,C)
       =G(a,C,\delta)\delta.
 \label{alg:gradient-difference}
\end{equation}
Both constructions use only addition, multiplication, and integer
binomial coefficients. The difference of any formal scalar function
at $C+\delta$ and $C$ similarly factors as a row times $\delta$.
\end{lemma}

\begin{remark}
\label{alg:formal-not-geometric}
The correction changes the graph of evaluation, while retaining the
separated formula for $\Psi$. It may mix all graph variables, and no
geometric realization of $\widetilde Y$ is required. The original
end-deviation cube law is used only before correction. Afterwards,
\eqref{alg:gradient-transport}--\eqref{alg:witness-transport} prove the
needed laws entirely within the common formal coefficient ring.
\end{remark}

\begin{lemma}[Prescribed wall collars]
\label{conn:wall-collar}
For a wall chart \((a_i,y_i)\), the connection in
Lemma~\ref{conn:image-bundle} can be chosen, in a formal frame on
a torus collar, to have total connection form
\begin{equation}
 U_i(a_i)\,d\theta_i+V_i(a_i,y_i)\,d\eta_i ,
 \label{conn:collar}
\end{equation}
with zero parameter components.  It still reduces to the given
flat family modulo \(\mathfrak d_i\).  The collar frame extends
to a global formal frame on \(J_i\) with \(A_i(0)=0\).
\end{lemma}

\begin{lemma}[Polarized variation]
\label{conn:variation}
Writing \(F_A=dA+A\wedge A\), every parameter variation satisfies
\begin{equation}
 \delta P_i
   =2\int_{J_i}\operatorname{tr}(\delta A_i\wedge F_{A_i})
          +2\epsilon_i\operatorname{tr}(V_i\,\delta U_i).
 \label{conn:variation-formula}
\end{equation}
Consequently \(P_i\in\mathfrak m_i^3\) and every coefficient of
its parameter differential lies in
\(\mathfrak k_i\mathbb C[[a_i,y_i]]\).
\end{lemma}

\begin{proposition}[Generation of the full defect ideal]
\label{conn:derivative-ideal}
In \(B=\mathbb C[[a,t]]\),
\begin{equation}
 \bigl(\partial_C\Psi(a,Y(a,t))\bigr)=\mathfrak r.
 \label{conn:derivative-identity}
\end{equation}
\end{proposition}

\begin{proposition}[The square-ideal value identity]
\label{conn:value-ideal}
For the same maps and potential,
\begin{equation}
 \Psi(a,Y(a,t))\in\mathfrak r^2 .
 \label{conn:value-identity}
\end{equation}
\end{proposition}

\begin{lemma}[A finite adjoint spanning set]\label{geo:spanning}
For the word set $\mathcal H$ fixed in Section~\ref{sec:geometry} and
the representation in \eqref{geo:matrices}, one has
\[
 \operatorname{span}_{\mathbb C}
 \{\operatorname{Ad}\rho(c):c\in\mathcal H\}
       =\operatorname{End}_{\mathbb C}(\mathfrak l).
\]
\end{lemma}

\begin{proposition}[Cubic nilpotence]
\label{def:cubic-nilpotence}
In \(B/\mathfrak r\), where \(B=\mathbb C[[a,t]]\), let
\(\mathfrak n\) be generated by all matrix entries of the end
holonomies minus \(1\).  Then
\begin{equation}
 \mathfrak n^3=0.
 \label{def:n-cube}
\end{equation}
In particular, for either restriction map in
\eqref{def:restriction-maps},
\begin{equation}
 (\iota_i^\pm)^*(\mathfrak k_i)^3\subset\mathfrak r .
 \label{def:k-cube}
\end{equation}
The same conclusion holds for the cube of the sum of all these
pulled-back ideals.
\end{proposition}

\begin{theorem}[Nonexistence of the formal data]
\label{frob:no-data}
Let $\Bbbk$ be a field of prime characteristic $\ell>2$, and let
$d\geq5$.  For $1\leq i\leq d$, choose an integer $n_i\geq0$, a tuple
$a_i=(a_{i,1},a_{i,2},a_{i,3})$ of variables, and a tuple $y_i$ of
$n_i$ variables.
Put $D=\sum_i n_i$, write $a=(a_1,\ldots,a_d)$, and let
$C=(C_i^+,C_i^-)_{i=1}^d$ be $2D$ variables, with $n_i$ variables in
each indicated block.  There do not exist series
\[
 P_i\in(a_i,y_i)^3\Bbbk[[a_i,y_i]],\qquad
 Y=(Y_i^+,Y_i^-)_{i=1}^d\in
       (a,t)\Bbbk[[a,t]]^{2D},\qquad t=(t_1,\ldots,t_D),
\]
having the following properties.  Define
\begin{equation}
 \Psi(a,C)=\sum_{i=1}^d
       \bigl(P_i(a_i,C_i^+)-P_i(0,C_i^-)\bigr),\qquad
 p_i(y_i)=(\partial_{a_{i,1}}P_i)(0,y_i),
 \label{frob:separated}
\end{equation}
and let $\sigma$ interchange the $+$ and $-$ blocks for each $i$.
All indicated derivatives are taken before substitution.
First, the two linear maps
\[
 A=\partial_tY(0,0),\qquad \sigma A:
                  \Bbbk^D\longrightarrow\Bbbk^{2D}
\]
have complementary images and are injective, or equivalently the square
matrix $[A\ \sigma A]$ is invertible.  Second,
\begin{equation}
                         \Psi(a,Y(a,t))=0.
 \label{frob:graph-zero}
\end{equation}
Finally, for every $i,j,k$ (including repetitions), both memberships
\begin{equation}
 \begin{split}
 a_{i,1}a_{j,1}a_{k,1}&\in J_Y,\\
 p_i(Y_i^-(a,t))p_j(Y_j^-(a,t))p_k(Y_k^-(a,t))&\in J_Y,
 \qquad
 J_Y=\bigl((\partial_{C_\nu}\Psi)(a,Y(a,t))\bigr)_{\nu=1}^{2D}
 \end{split}
 \label{frob:memberships}
\end{equation}
hold in $\Bbbk[[a,t]]$.
\end{theorem}

\begin{lemma}[Normal cycles and restricted memberships]
\label{frob:normal-cycle}
Suppose that $\Gamma$ is a formal smooth $D$-dimensional graph in the
$C$ variables, centered at the origin, with $F|_\Gamma=0$.  Complete a
parametrization to formal coordinates $(t,u)$, with $\Gamma$ given by
$u_1=\cdots=u_D=0$.  In $\Omega$ its normal form
\begin{equation}
 \gamma=\left(\prod_{b=1}^D u_b^{\ell-1}\right)
                    \mathrm du_1\wedge\cdots\wedge\mathrm du_D
 \label{frob:normal-form}
\end{equation}
is annihilated by the normal ideal $(u)$ and satisfies
$\mathrm d\gamma=\delta\gamma=0$.
If an ambient function $g$ has a restricted expression
\begin{equation}
  g|_\Gamma=\sum_{\nu=1}^{2D}h_\nu(t)
                               (\partial_{C_\nu}F)|_\Gamma,
 \label{frob:restricted-membership}
\end{equation}
then $g\gamma$ is a Koszul boundary.  More precisely, lift $h_\nu$ to
$\widetilde h_\nu(C)$ by the inverse tangential coordinates and let
$\iota_\nu$ be contraction with $\partial/\partial C_\nu$.  Then
\begin{equation}
 g\gamma=\delta\left(\sum_\nu
                         \widetilde h_\nu\iota_\nu\gamma\right).
 \label{frob:primitive-general}
\end{equation}
If two such graphs have complementary tangent spaces, their normal
forms have nonzero residue pairing.
\end{lemma}

\begin{lemma}[Joint kernels in a tensor product]
\label{frob:tensor-kernel}
For finite-dimensional vector spaces $V_i$ and endomorphisms $S_i$,
put $N_i=\ker S_i$, and let $W$ be an additional tensor factor on which
all $S_i$ act as the identity.  On
$V_1\otimes\cdots\otimes V_d\otimes W$ one has
\begin{equation}
 \bigcap_{|I|=3}\ker\left(\prod_{i\in I}S_i\right)
 =\sum_{|J|\geq d-2}
   \left(\bigotimes_{i=1}^d V_i(J)\right)\otimes W,
 \qquad
 V_i(J)=\begin{cases}N_i&i\in J,\\ V_i&i\notin J.\end{cases}
 \label{frob:tensor-kernel-identity}
\end{equation}
This also holds with additional passive factors interspersed in any
fixed tensor order.
\end{lemma}

\begin{corollary}[The exact algebraic input]\label{geo:input-invariants}
There are orientations and whiskers for the discs and spheres such
that, for all $r,s\in\mathcal R$ and
$R=\mathbb Z[\pi_1(M)]$,
\begin{equation}\label{geo:invariants}
 \lambda(f_r,g_s)=\delta_{rs}\,1\in R,
 \qquad \lambda(g_r,g_s)=0\in R,
 \qquad \widetilde\mu(g_r)=0.
\end{equation}
In particular the normal second Stiefel--Whitney number of every
$g_r$ is zero.  These data satisfy all algebraic and boundary
hypotheses of the unrestricted disc-embedding assertion.
\end{corollary}

\begin{corollary}[Nongoodness of the free group]\label{cor:nongood}
The free group $F_2$ on two generators is not good in the sense of
Freedman--Quinn. Every group containing a subgroup isomorphic to $F_2$
is likewise not good.
\end{corollary}

\begin{corollary}\label{cor:surgery-conjunction}
The unrestricted topological surgery and $s$-cobordism assertions
cannot both hold.
\end{corollary}
